6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":1192,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 3.34\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T86b,"])self.__next_f.push([1,"Those who are in Kṛṣṇa consciousness are naturally reluctant to engage in material sense gratification. But those who are not in such consciousness should follow the rules and regulations of the revealed scriptures. Unrestricted sense enjoyment is the cause of material encagement, but one who follows the rules and regulations of the revealed scriptures does not become entangled by the sense objects. For example, sex enjoyment is a necessity for the conditioned soul, and sex enjoyment is allowed under the license of marriage ties. According to scriptural injunctions, one is forbidden to engage in sex relationships with any women other than one’s wife. All other women are to be considered as one’s mother. But in spite of such injunctions, a man is still inclined to have sex relationships with other women. These propensities are to be curbed; otherwise they will be stumbling blocks on the path of self-realization. As long as the material body is there, the necessities of the material body are allowed, but under rules and regulations. And yet, we should not rely upon the control of such allowances. One has to follow those rules and regulations, unattached to them, because practice of sense gratification under regulations may also lead one to go astray – as much as there is always the chance of an accident, even on the royal roads. Although they may be very carefully maintained, no one can guarantee that there will be no danger even on the safest road. The sense enjoyment spirit has been current a very long, long time, owing to material association. Therefore, in spite of regulated sense enjoyment, there is every chance of falling down; therefore any attachment for regulated sense enjoyment must also be avoided by all means. But attachment to Kṛṣṇa consciousness, or acting always in the loving service of Kṛṣṇa, detaches one from all kinds of sensory activities. Therefore, no one should try to be detached from Kṛṣṇa consciousness at any stage of life. The whole purpose of detachment from all kinds of sense attachment is ultimately to become situated on the platform of Kṛṣṇa consciousness."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":1192,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"34\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 34\",\"advanced_view_url_path\":\"/en/library/bg/3/advanced-view/#bb1059\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Бълга