6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":1198,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 3.35\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T88c,"])self.__next_f.push([1,"One should therefore discharge his prescribed duties in full Kṛṣṇa consciousness rather than those prescribed for others. Materially, prescribed duties are duties enjoined according to one’s psychophysical condition, under the spell of the modes of material nature. Spiritual duties are as ordered by the spiritual master for the transcendental service of Kṛṣṇa. But whether material or spiritual, one should stick to his prescribed duties even up to death, rather than imitate another’s prescribed duties. Duties on the spiritual platform and duties on the material platform may be different, but the principle of following the authorized direction is always good for the performer. When one is under the spell of the modes of material nature, one should follow the prescribed rules for his particular situation and should not imitate others. For example, a brāhmaṇa, who is in the mode of goodness, is nonviolent, whereas a kṣatriya, who is in the mode of passion, is allowed to be violent. As such, for a kṣatriya it is better to be vanquished following the rules of violence than to imitate a brāhmaṇa who follows the principles of nonviolence. Everyone has to cleanse his heart by a gradual process, not abruptly. However, when one transcends the modes of material nature and is fully situated in Kṛṣṇa consciousness, he can perform anything and everything under the direction of a bona fide spiritual master. In that complete stage of Kṛṣṇa consciousness, the kṣatriya may act as a brāhmaṇa, or a brāhmaṇa may act as a kṣatriya. In the transcendental stage, the distinctions of the material world do not apply. For example, Viśvāmitra was originally a kṣatriya, but later on he acted as a brāhmaṇa, whereas Paraśurāma was a brāhmaṇa but later on he acted as a kṣatriya. Being transcendentally situated, they could do so; but as long as one is on the material platform, he must perform his duties according to the modes of material nature. At the same time, he must have a full sense of Kṛṣṇa consciousness."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":1198,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"35\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 35\",\"advanced_view_url_path\":\"/en/library/bg/3/advanced-view/#bb1064\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/3/35/\"},{\"disp